const express = require('express');
const mysql = require('mysql2');
const cors = require('cors');

const app = express();
app.use(cors());
app.use(express.json());

// Conexão com o MySQL
const db = mysql.createConnection({
  host: 'localhost',
  user: 'root',
  password: 'sua_senha_aqui', // Altere para a senha do seu MySQL
  database: 'BD_FAZENDA_INTELIGENTE'
});

db.connect(err => {
  if (err) {
    console.error('Erro ao conectar ao banco:', err);
  } else {
    console.log('Conectado ao banco de dados MySQL!');
  }
});

// Rota do Dashboard
app.get('/api/dashboard/stats', (req, res) => {
  const query = `
    SELECT 
      (SELECT COUNT(*) FROM SENSOR) AS sensores_totais,
      (SELECT COUNT(*) FROM FAZENDA) AS fazendas,
      (SELECT COUNT(*) FROM USUARIOS) AS usuarios
  `;
  db.query(query, (err, results) => {
    if (err) return res.status(500).json({ error: err.message });
    res.json(results[0]);
  });
});

app.listen(3000, () => {
  console.log('Servidor rodando na porta 3000');
});

// Rota para listar todas as culturas
app.get('/api/crops', (req, res) => {
  // Ajuste os nomes dos campos SQL de acordo com a sua tabela CULTURA
  const query = `
    SELECT 
      ID_CULTURA AS id,
      NOME AS name,
      TIPO AS type,
      STATUS AS status,
      SAUDE AS health,
      AREA AS area,
      SAFRA AS season
    FROM CULTURA
  `;

  db.query(query, (err, results) => {
    if (err) {
      return res.status(500).json({ error: 'Erro ao buscar culturas: ' + err.message });
    }
    res.json(results);
  });
});

// Buscar todos os alertas
app.get('/api/alerts', (req, res) => {
  const query = `
    SELECT 
      a.ID_ALERTA AS id,
      a.TITULO AS title,
      a.MENSAGEM AS message,
      a.TIPO AS type,
      a.SEVERIDADE AS severity,
      s.NOME AS sensorName,
      a.IS_READ AS isRead,
      a.DATA_CRIACAO AS createdDate
    FROM ALERTA a
    LEFT JOIN SENSOR s ON a.ID_SENSOR = s.ID_SENSOR
    ORDER BY a.ID_ALERTA DESC
  `;
  db.query(query, (err, results) => {
    if (err) return res.status(500).json({ error: err.message });
    const formatted = results.map(row => ({
      ...row,
      isRead: row.isRead === 1 || row.isRead === true
    }));
    res.json(formatted);
  });
});

// Marcar um alerta como lido
app.put('/api/alerts/:id/read', (req, res) => {
  const query = 'UPDATE ALERTA SET IS_READ = 1 WHERE ID_ALERTA = ?';
  db.query(query, [req.params.id], (err) => {
    if (err) return res.status(500).json({ error: err.message });
    res.json({ success: true });
  });
});

// Marcar todos os alertas como lidos
app.put('/api/alerts/read-all', (req, res) => {
  const query = 'UPDATE ALERTA SET IS_READ = 1';
  db.query(query, (err) => {
    if (err) return res.status(500).json({ error: err.message });
    res.json({ success: true });
  });
});

// Deletar um alerta
app.delete('/api/alerts/:id', (req, res) => {
  const query = 'DELETE FROM ALERTA WHERE ID_ALERTA = ?';
  db.query(query, [req.params.id], (err) => {
    if (err) return res.status(500).json({ error: err.message });
    res.json({ success: true });
  });
});